div.script:
//
/* ============================================================
   BUKU WORKSPACE - SPA APPLICATION
   ============================================================ */
(function(){
'use strict';

const CONFIG = {
  API_URL: '', // <-- ISI URL Web App Google Apps Script Anda di sini, contoh: 'https://script.google.com/macros/s/DEPLOYMENT_ID/exec'
  APP_NAME: 'Buku Workspace',
  VERSION: '2.0.0',
  CACHE_KEY: 'bw2_cache',
  TOKEN_KEY: 'bw2_token',
  USER_KEY: 'bw2_user'
};

const S = {
  user: null,
  token: localStorage.getItem(CONFIG.TOKEN_KEY) || '',
  route: 'dashboard',
  routeParam: null,
  settings: {},
  books: [],
  chapters: [],
  discussions: [],
  quizzes: [],
  myLogs: [],
  myQuizResults: [],
  publicLogs: [],
  users: [],
  allLogs: [],
  allQuizResults: [],
  stats: {},
  loading: false,
  cache: null
};

const $ = (sel, ctx=document) => ctx.querySelector(sel);
const $$ = (sel, ctx=document) => Array.from(ctx.querySelectorAll(sel));
const esc = (s='') => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const uid = () => 'tmp_' + Math.random().toString(36).slice(2,10);
const fmtDate = (iso) => { if(!iso) return '-'; const d=new Date(iso); if(isNaN(d)) return iso; return d.toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'}); };
const fmtDateTime = (iso) => { if(!iso) return '-'; const d=new Date(iso); if(isNaN(d)) return iso; return d.toLocaleString('id-ID',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}); };
const isAdmin = () => S.user && String(S.user.role).toLowerCase() === 'admin';
const pageTitle = (t) => { document.title = t ? t + ' — ' + CONFIG.APP_NAME : CONFIG.APP_NAME; };

function toast(msg, type='success') {
  const wrap = $('#toastWrap');
  const el = document.createElement('div');
  el.className = 'toast ' + (type==='error'?'error':type==='warn'?'warn':'success');
  el.innerHTML = '<div class="toast-msg">'+esc(msg)+'</div>';
  wrap.appendChild(el);
  setTimeout(()=>{ el.style.opacity='0'; el.style.transform='translateY(-8px)'; setTimeout(()=>el.remove(),250); }, 3400);
}

function setBtnLoading(btn, loading, label) {
  if(!btn) return;
  if(loading){ btn.disabled=true; btn.dataset.orig=btn.innerHTML; btn.innerHTML='<span class="spinner"></span>'+(label?esc(label):'Memproses...'); }
  else { btn.disabled=false; if(btn.dataset.orig){ btn.innerHTML=btn.dataset.orig; delete btn.dataset.orig; } }
}

async function api(action, data={}, method='POST') {
  if(!CONFIG.API_URL) throw new Error('API_URL belum diatur. Buka file theme.xml dan isi CONFIG.API_URL dengan URL Web App Apps Script Anda.');
  const payload = Object.assign({ action, token: S.token, data }, {});
  // use POST with text/plain to avoid CORS preflight on Apps Script
  const res = await fetch(CONFIG.API_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'text/plain;charset=utf-8' },
    body: JSON.stringify(payload)
  });
  const text = await res.text();
  let json;
  try { json = JSON.parse(text); } catch(e) { throw new Error('Respons server tidak valid.'); }
  if(!json.success) {
    const err = new Error(json.message || 'Terjadi kesalahan.');
    err.code = json.code; err.data = json.data;
    throw err;
  }
  return json.data;
}

async function apiGet(action, params={}) {
  if(!CONFIG.API_URL) throw new Error('API_URL belum diatur.');
  const u = new URL(CONFIG.API_URL);
  u.searchParams.set('action', action);
  if(S.token) u.searchParams.set('token', S.token);
  Object.keys(params).forEach(k=>{ if(params[k]!==undefined&&params[k]!==null) u.searchParams.set(k, params[k]); });
  const res = await fetch(u.toString());
  const json = await res.json();
  if(!json.success) throw new Error(json.message || 'Gagal memuat data.');
  return json.data;
}

function saveSession() {
  if(S.token) localStorage.setItem(CONFIG.TOKEN_KEY, S.token); else localStorage.removeItem(CONFIG.TOKEN_KEY);
  if(S.user) localStorage.setItem(CONFIG.USER_KEY, JSON.stringify(S.user)); else localStorage.removeItem(CONFIG.USER_KEY);
}
function loadSession() {
  try { S.user = JSON.parse(localStorage.getItem(CONFIG.USER_KEY) || 'null'); } catch(e){ S.user=null; }
  S.token = localStorage.getItem(CONFIG.TOKEN_KEY) || '';
}
function clearSession() { S.token=''; S.user=null; saveSession(); }

function cacheSet(data){ try{ localStorage.setItem(CONFIG.CACHE_KEY, JSON.stringify({t:Date.now(),d:data})); }catch(e){} }
function cacheGet(){ try{ const r=JSON.parse(localStorage.getItem(CONFIG.CACHE_KEY)||'null'); return r&&r.d?r.d:null; }catch(e){ return null; } }

/* ---------- Modal ---------- */
function openModal({title, sub='', body='', footer='', size=''}) {
  $('#modalTitle').textContent = title || '';
  $('#modalSub').textContent = sub || '';
  $('#modalSub').style.display = sub ? '' : 'none';
  $('#modalBody').innerHTML = body;
  $('#modalFooter').innerHTML = footer;
  $('#modalFooter').style.display = footer ? '' : 'none';
  const box = $('#modalBox');
  box.className = 'modal' + (size ? ' modal-' + size : '');
  $('#modalBackdrop').classList.add('open');
  document.body.classList.add('modal-open');
}
function closeModal() {
  $('#modalBackdrop').classList.remove('open');
  document.body.classList.remove('modal-open');
}
$('#modalBackdrop').addEventListener('click', (e)=>{ if(e.target.id==='modalBackdrop') closeModal(); });
document.addEventListener('keydown', (e)=>{ if(e.key==='Escape') closeModal(); });

function confirmDialog({title='Konfirmasi', message='Yakin?', confirmText='Hapus', confirmClass='btn-danger', onConfirm}) {
  openModal({
    title, sub:'', size:'sm',
    body: `<p style="font-size:16px;color:var(--text-body);margin:0;line-height:1.7">${esc(message)}</p>`,
    footer: `<button class="btn btn-secondary" id="confirmCancelBtn">Batal</button><button class="btn ${confirmClass}" id="confirmOkBtn">${esc(confirmText)}</button>`
  });
  $('#confirmCancelBtn').onclick = closeModal;
  $('#confirmOkBtn').onclick = async () => {
    const btn = $('#confirmOkBtn');
    setBtnLoading(btn, true, 'Memproses...');
    try { await onConfirm(); closeModal(); } catch(err){ toast(err.message,'error'); setBtnLoading(btn,false); }
  };
}

/* ---------- Image helpers ---------- */
function readFileAsDataURL(file) {
  return new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = () => resolve(r.result);
    r.onerror = () => reject(new Error('Gagal membaca file.'));
    r.readAsDataURL(file);
  });
}
async function fileToImagePayload(file, maxDim=1400, quality=0.85) {
  if(!file) return null;
  const allowed = ['image/jpeg','image/png','image/webp','image/gif'];
  if(!allowed.includes(file.type)) throw new Error('Format gambar harus JPG, PNG, WEBP, atau GIF.');
  if(file.size > 4 * 1024 * 1024) throw new Error('Ukuran gambar maksimal 4MB.');
  // GIF: skip canvas resize to preserve animation
  if(file.type === 'image/gif') {
    const dataUrl = await readFileAsDataURL(file);
    return { image_base64: dataUrl, filename: file.name, mime_type: file.type };
  }
  const dataUrl = await readFileAsDataURL(file);
  const img = await new Promise((resolve, reject)=>{ const i=new Image(); i.onload=()=>resolve(i); i.onerror=()=>reject(new Error('Gambar tidak valid.')); i.src=dataUrl; });
  let {width:w, height:h} = img;
  const scale = Math.min(1, maxDim / Math.max(w,h));
  w = Math.round(w*scale); h = Math.round(h*scale);
  const c = document.createElement('canvas'); c.width=w; c.height=h;
  c.getContext('2d').drawImage(img,0,0,w,h);
  const mime = file.type === 'image/png' ? 'image/png' : 'image/jpeg';
  const out = c.toDataURL(mime, quality);
  return { image_base64: out, filename: file.name.replace(/\.[^.]+$/, '') + (mime==='image/png'?'.png':'.jpg'), mime_type: mime };
}

function bindImageUpload(containerId, opts={}) {
  const wrap = document.getElementById(containerId);
  if(!wrap) return;
  const input = wrap.querySelector('input[type=file]');
  const preview = wrap.querySelector('[data-preview]');
  const placeholder = wrap.querySelector('[data-placeholder]');
  const removeBtn = wrap.querySelector('[data-remove]');
  const status = wrap.querySelector('[data-status]');
  let payload = null;
  let removed = false;
  wrap._getPayload = () => payload;
  wrap._isRemoved = () => removed;
  wrap._reset = () => { payload=null; removed=false; input.value=''; if(preview){preview.src=opts.currentUrl||''; preview.style.display=opts.currentUrl?'block':'none';} if(placeholder) placeholder.style.display=opts.currentUrl?'none':''; if(status) status.textContent=''; };
  if(input) input.addEventListener('change', async (e)=>{
    const file = e.target.files && e.target.files[0];
    if(!file) return;
    try {
      if(status) status.textContent = 'Memproses gambar...';
      payload = await fileToImagePayload(file);
      removed = false;
      if(preview){ preview.src = payload.image_base64; preview.style.display='block'; }
      if(placeholder) placeholder.style.display='none';
      if(status) status.textContent = 'Gambar siap diunggah.';
    } catch(err){ toast(err.message,'error'); if(status) status.textContent=''; input.value=''; }
  });
  if(removeBtn) removeBtn.addEventListener('click', ()=>{
    payload = null; removed = true; input.value='';
    if(preview){ preview.src=''; preview.style.display='none'; }
    if(placeholder) placeholder.style.display='';
    if(status) status.textContent = 'Gambar akan dihapus saat disimpan.';
  });
  return wrap;
}

/* ---------- State mapping ---------- */
function applyInitData(data) {
  if(!data) return;
  S.settings = data.settings || S.settings || {};
  S.books = data.books || [];
  S.chapters = data.chapters || [];
  S.discussions = data.discussions || [];
  S.quizzes = data.quizzes || [];
  S.myLogs = data.myLogs || [];
  S.myQuizResults = data.myQuizResults || [];
  S.publicLogs = data.publicLogs || [];
  S.stats = data.stats || {};
  if(data.currentUser) { S.user = Object.assign({}, S.user||{}, data.currentUser); saveSession(); }
  if(data.users) S.users = data.users;
  if(data.allLogs) S.allLogs = data.allLogs;
  if(data.allQuizResults) S.allQuizResults = data.allQuizResults;
  cacheSet(data);
}

/* ---------- Navigation ---------- */
const ROUTES = {
  dashboard: { title:'Dashboard', sub:'Ringkasan aktivitas membaca Anda' },
  books: { title:'Katalog Buku', sub:'Kelola dan jelajahi koleksi buku' },
  bookDetail: { title:'Detail Buku', sub:'Informasi buku, bab, dan aktivitas' },
  logs: { title:'Jurnal Baca', sub:'Catat dan pantau progres membaca Anda' },
  discussions: { title:'Diskusi', sub:'Ruang percakapan komunitas baca' },
  quizzes: { title:'Kuis', sub:'Uji pemahaman bacaan Anda' },
  users: { title:'Pengguna', sub:'Kelola anggota workspace', admin:true },
  settings: { title:'Pengaturan', sub:'Konfigurasi workspace', admin:true },
  profile: { title:'Profil Saya', sub:'Kelola informasi akun Anda' }
};

function navigate(route, param=null) {
  if(ROUTES[route] && ROUTES[route].admin && !isAdmin()) { toast('Akses khusus admin.','warn'); return; }
  S.route = route; S.routeParam = param;
  location.hash = '#/' + route + (param ? '/' + encodeURIComponent(param) : '');
  renderRoute();
}
function renderRoute() {
  const r = ROUTES[S.route] || ROUTES.dashboard;
  $('#topbarTitle').textContent = r.title;
  $('#topbarSub').textContent = r.sub;
  pageTitle(r.title);
  $$('.sidebar-link').forEach(b=>b.classList.toggle('active', b.dataset.route===S.route || (S.route==='bookDetail'&&b.dataset.route==='books')));
  $$('.bottom-nav-item').forEach(b=>b.classList.toggle('active', b.dataset.route===S.route || (S.route==='bookDetail'&&b.dataset.route==='books') || (['users','settings','profile','quizzes'].includes(S.route)&&b.dataset.route==='more')));
  $$('.admin-only').forEach(el=>el.style.display = isAdmin() ? '' : 'none');
  updateUserUI();
  const content = $('#appContent');
  content.style.opacity='0'; content.style.transform='translateY(8px)';
  setTimeout(()=>{
    try {
      switch(S.route){
        case 'dashboard': renderDashboard(content); break;
        case 'books': renderBooks(content); break;
        case 'bookDetail': renderBookDetail(content, S.routeParam); break;
        case 'logs': renderLogs(content); break;
        case 'discussions': renderDiscussions(content); break;
        case 'quizzes': renderQuizzes(content); break;
        case 'users': renderUsers(content); break;
        case 'settings': renderSettings(content); break;
        case 'profile': renderProfile(content); break;
        default: renderDashboard(content);
      }
    } catch(e){ console.error(e); content.innerHTML = `<div class="panel"><p style="color:var(--rose);font-weight:600">Gagal merender halaman: ${esc(e.message)}</p></div>`; }
    content.style.transition='opacity .22s cubic-bezier(.16,1,.3,1), transform .22s cubic-bezier(.16,1,.3,1)';
    requestAnimationFrame(()=>{ content.style.opacity='1'; content.style.transform='translateY(0)'; });
  }, 30);
}

function updateUserUI() {
  const name = S.user ? S.user.name : 'Tamu';
  const role = S.user ? S.user.role : 'guest';
  const initial = (name||'U').trim().charAt(0).toUpperCase();
  $('#sidebarUserName').textContent = name;
  $('#sidebarUserRole').textContent = role;
  const setAvatar = (el) => {
    if(!el) return;
    if(S.user && S.user.avatar_url){ el.innerHTML = `<img src="${esc(S.user.avatar_url)}" alt="${esc(name)}" style="width:100%;height:100%;object-fit:cover;border-radius:50%"/>`; }
    else { el.textContent = initial; el.style.background=''; }
  };
  setAvatar($('#sidebarAvatar')); setAvatar($('#topbarAvatar'));
}

window.addEventListener('hashchange', () => {
  const h = location.hash.replace(/^#\//,'');
  if(!h || h==='home') return;
  const parts = h.split('/');
  const route = parts[0];
  const param = parts[1] ? decodeURIComponent(parts[1]) : null;
  if(ROUTES[route]) { S.route = route; S.routeParam = param; if($('#appShell').classList.contains('active')) renderRoute(); }
});

function openMoreMenu() {
  const adminItems = isAdmin() ? `
    <button class="btn btn-secondary btn-block" onclick="closeModal();BW.navigate('quizzes')">Kuis</button>
    <button class="btn btn-secondary btn-block" onclick="closeModal();BW.navigate('users')">Pengguna</button>
    <button class="btn btn-secondary btn-block" onclick="closeModal();BW.navigate('settings')">Pengaturan</button>
  ` : `<button class="btn btn-secondary btn-block" onclick="closeModal();BW.navigate('quizzes')">Kuis</button>`;
  openModal({
    title:'Menu', sub:'Navigasi cepat', size:'sm',
    body:`<div style="display:grid;gap:10px">
      <button class="btn btn-secondary btn-block" onclick="closeModal();BW.navigate('profile')">Profil Saya</button>
      ${adminItems}
      <button class="btn btn-danger btn-block" onclick="closeModal();BW.logout()">Keluar</button>
    </div>`,
    footer:''
  });
}

/* ---------- Render helpers ---------- */
function bookCoverHTML(book, cls='') {
  const url = book.cover_url || '';
  const title = esc(book.title||'Buku');
  if(url) return `<img src="${esc(url)}" alt="${title}" class="${cls}" style="width:100%;height:100%;object-fit:cover" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'"/><div class="book-cover-placeholder ${cls}" style="display:none">${title}</div>`;
  const colors = [['#E0E7FF','#C7D2FE','#4338CA'],['#D1FAE5','#A7F3D0','#065F46'],['#FEF3C7','#FDE68A','#92400E'],['#DBEAFE','#BFDBFE','#1E40AF'],['#FCE7F3','#FBCFE8','#9D174D']];
  const c = colors[(String(book.title||'').length) % colors.length];
  return `<div class="book-cover-placeholder ${cls}" style="background:linear-gradient(135deg,${c[0]},${c[1]});color:${c[2]}">${title}</div>`;
}
function avatarHTML(user, size='sm') {
  const name = esc((user&&user.name)||'U');
  const initial = name.trim().charAt(0).toUpperCase();
  const url = user && user.avatar_url;
  if(url) return `<img src="${esc(url)}" alt="${name}" class="avatar ${size}" onerror="this.outerHTML='<div class=\\'avatar ${size}\\'>${initial}</div>'"/>`;
  return `<div class="avatar ${size}">${initial}</div>`;
}
function emptyState(icon, title, desc, actionHTML='') {
  return `<div class="empty-state"><div class="empty-icon">${icon}</div><h3>${esc(title)}</h3><p>${esc(desc)}</p>${actionHTML}</div>`;
}
const ICON_BOOK = '<svg class="icon-lg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/></svg>';
const ICON_LOG = '<svg class="icon-lg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg>';
const ICON_CHAT = '<svg class="icon-lg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>';

/* ---------- Dashboard ---------- */
function renderDashboard(el) {
  const logs = S.myLogs || [];
  const pages = logs.reduce((s,l)=>s+Number(l.pages_read||0),0);
  const mins = logs.reduce((s,l)=>s+Number(l.duration_mins||0),0);
  const streak = calcStreak(logs);
  const recent = logs.slice(0,5);
  const activeBooks = S.books.filter(b=>b.status==='active').slice(0,4);
  el.innerHTML = `
    <div class="page-header">
      <div><h2>Halo, ${esc((S.user&&S.user.name)||'Pembaca')} 👋</h2><p>Terus bangun kebiasaan membaca Anda hari ini.</p></div>
      <div class="page-header-actions">
        <button class="btn btn-primary" onclick="BW.openLogForm()"><svg class="icon-sm" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14M5 12h14"/></svg>Catat Bacaan</button>
      </div>
    </div>
    <div class="stat-grid">
      <div class="stat-card"><div class="stat-label">📚 Buku Aktif</div><div class="stat-val">${S.books.filter(b=>b.status==='active').length}</div></div>
      <div class="stat-card"><div class="stat-label">📖 Halaman Dibaca</div><div class="stat-val">${pages}</div></div>
      <div class="stat-card"><div class="stat-label">🔥 Streak</div><div class="stat-val">${streak} <span style="font-size:16px;font-weight:600;color:var(--text-muted)">hari</span></div></div>
      <div class="stat-card"><div class="stat-label">⏱ Menit Baca</div><div class="stat-val">${mins}</div></div>
    </div>
    <div class="grid-2" style="gap:24px">
      <div class="panel">
        <div class="panel-header"><h3 class="panel-title">Jurnal Terbaru</h3><button class="btn btn-ghost btn-sm" onclick="BW.navigate('logs')">Lihat semua</button></div>
        ${recent.length ? recent.map(l=>`
          <div class="list-item">
            <div class="avatar sm" style="background:var(--primary-soft);color:var(--primary)"><svg class="icon-sm" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/></svg></div>
            <div class="list-item-body">
              <div class="list-item-title">${esc(l.book_title||'Buku')}</div>
              <div class="list-item-meta">${l.pages_read||0} halaman • ${l.duration_mins||0} menit • ${fmtDate(l.created_at)}</div>
              ${l.reflection ? `<div style="font-size:14px;color:var(--text-muted);margin-top:4px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden">${esc(l.reflection)}</div>`:''}
            </div>
          </div>`).join('') : emptyState(ICON_LOG,'Belum ada jurnal','Mulai catat bacaan pertama Anda untuk membangun kebiasaan.',`<button class="btn btn-primary btn-sm" onclick="BW.openLogForm()">Catat Bacaan</button>`)}
      </div>
      <div class="panel">
        <div class="panel-header"><h3 class="panel-title">Buku Aktif</h3><button class="btn btn-ghost btn-sm" onclick="BW.navigate('books')">Lihat semua</button></div>
        ${activeBooks.length ? activeBooks.map(b=>`
          <div class="list-item" style="cursor:pointer" onclick="BW.navigate('bookDetail','${esc(b.id)}')">
            <div style="width:52px;height:70px;border-radius:8px;overflow:hidden;background:var(--bg-soft);flex-shrink:0">${bookCoverHTML(b)}</div>
            <div class="list-item-body">
              <div class="list-item-title">${esc(b.title)}</div>
              <div class="list-item-meta">${esc(b.author||'-')} • ${esc(b.category||'Umum')}</div>
              <div style="font-size:13px;color:var(--text-light);margin-top:4px">${Number(b.total_pages||0)} halaman</div>
            </div>
            <span class="badge badge-primary">${esc(b.status)}</span>
          </div>`).join('') : emptyState(ICON_BOOK,'Belum ada buku','Buku aktif akan tampil di sini.', isAdmin()?`<button class="btn btn-primary btn-sm" onclick="BW.openBookForm()">Tambah Buku</button>`:'')}
      </div>
    </div>`;
}
function calcStreak(logs) {
  const days = [...new Set(logs.map(l=>String(l.created_at||'').slice(0,10)).filter(Boolean))].sort().reverse();
  if(!days.length) return 0;
  const today = new Date(); const fmt=d=>d.toISOString().slice(0,10);
  const t=fmt(today), y=fmt(new Date(today.getTime()-86400000));
  if(!days.includes(t) && !days.includes(y)) return 0;
  let count=0, ptr=new Date(days.includes(t)?today:y);
  while(days.includes(fmt(ptr))){ count++; ptr=new Date(ptr.getTime()-86400000); }
  return count;
}

/* ---------- Books ---------- */
function renderBooks(el) {
  const q = ($('#bookSearchInput')?.value || S._bookQuery || '').toLowerCase();
  const statusFilter = S._bookStatus || 'all';
  let books = S.books.slice();
  if(statusFilter!=='all') books = books.filter(b=>b.status===statusFilter);
  if(q) books = books.filter(b => (b.title+' '+b.author+' '+b.category).toLowerCase().includes(q));
  el.innerHTML = `
    <div class="page-header">
      <div><h2>Katalog Buku</h2><p>Temukan dan kelola koleksi bacaan kelas Anda.</p></div>
      <div class="page-header-actions">
        ${isAdmin()?`<button class="btn btn-primary" onclick="BW.openBookForm()"><svg class="icon-sm" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14M5 12h14"/></svg>Tambah Buku</button>`:''}
      </div>
    </div>
    <div class="panel" style="margin-bottom:24px">
      <div style="display:flex;gap:12px;flex-wrap:wrap">
        <div class="input-icon-wrap" style="flex:1;min-width:220px"><svg class="input-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><path d="M21 21l-4.35-4.35"/></svg><input class="input" id="bookSearchInput" placeholder="Cari judul, penulis, kategori..." value="${esc(S._bookQuery||'')}" oninput="S._bookQuery=this.value;BW.renderBooks(document.getElementById('appContent'))"/></div>
        <select class="select" style="width:auto;min-width:180px" onchange="S._bookStatus=this.value;BW.renderBooks(document.getElementById('appContent'))">
          <option value="all" ${statusFilter==='all'?'selected':''}>Semua Status</option>
          <option value="active" ${statusFilter==='active'?'selected':''}>Aktif</option>
          <option value="upcoming" ${statusFilter==='upcoming'?'selected':''}>Mendatang</option>
          <option value="archived" ${statusFilter==='archived'?'selected':''}>Arsip</option>
        </select>
      </div>
    </div>
    ${books.length ? `<div class="grid-3">${books.map(b=>bookCardHTML(b)).join('')}</div>` : emptyState(ICON_BOOK,'Buku tidak ditemukan','Coba ubah pencarian atau tambahkan buku baru.', isAdmin()?`<button class="btn btn-primary btn-sm" onclick="BW.openBookForm()">Tambah Buku</button>`:'')}
  `;
}
function bookCardHTML(b) {
  const statusBadge = b.status==='active'?'<span class="badge badge-mint">Aktif</span>':b.status==='upcoming'?'<span class="badge badge-amber">Mendatang</span>':'<span class="badge badge-slate">Arsip</span>';
  const chaptersCount = S.chapters.filter(c=>c.book_id===b.id).length;
  return `<div class="book-card">
    <div class="book-cover" style="cursor:pointer" onclick="BW.navigate('bookDetail','${esc(b.id)}')">${bookCoverHTML(b)}<span class="book-badge">${statusBadge}</span></div>
    <div class="book-body">
      <div class="book-cat">${esc(b.category||'Umum')}</div>
      <h3 class="book-title" style="cursor:pointer" onclick="BW.navigate('bookDetail','${esc(b.id)}')">${esc(b.title)}</h3>
      <p class="book-author">${esc(b.author||'-')}</p>
      <div class="book-meta"><span>${Number(b.total_pages||0)} hal</span><span>${chaptersCount} bab</span></div>
    </div>
    <div class="book-actions">
      <button class="btn btn-secondary btn-sm" onclick="BW.navigate('bookDetail','${esc(b.id)}')">Detail</button>
      ${isAdmin()?`<button class="btn btn-ghost btn-sm" onclick="BW.openBookForm('${esc(b.id)}')">Edit</button><button class="btn btn-ghost btn-sm" style="color:var(--rose)" onclick="BW.deleteBook('${esc(b.id)}')">Hapus</button>`:''}
    </div>
  </div>`;
}

function openBookForm(id=null) {
  if(!isAdmin()){ toast('Hanya admin yang dapat mengelola buku.','warn'); return; }
  const b = id ? S.books.find(x=>x.id===id) : null;
  openModal({
    title: b ? 'Edit Buku' : 'Tambah Buku Baru',
    sub: b ? 'Perbarui informasi buku dan cover.' : 'Lengkapi informasi buku untuk katalog kelas.',
    size:'lg',
    body: `
      <form id="bookForm" class="form-grid">
        <div class="field full"><label>Cover Buku</label>
          <div class="img-upload" id="bookCoverUpload">
            ${b&&b.cover_url?`<img data-preview src="${esc(b.cover_url)}" class="img-upload-preview" style="display:block"/>`:`<img data-preview class="img-upload-preview" style="display:none"/>`}
            <div data-placeholder style="${b&&b.cover_url?'display:none':''};color:var(--text-muted);font-size:14px;margin-bottom:8px">Unggah cover buku (JPG, PNG, WEBP, GIF, maks 4MB)</div>
            <div class="img-upload-actions">
              <label class="btn btn-secondary btn-sm" style="cursor:pointer"><input type="file" accept="image/*"/>Pilih Gambar</label>
              <button type="button" class="btn btn-ghost btn-sm" data-remove>Hapus Gambar</button>
            </div>
            <div class="field-hint" data-status></div>
          </div>
        </div>
        <div class="field"><label>Judul Buku *</label><input class="input" name="title" required maxlength="200" value="${esc(b?b.title:'')}" placeholder="Contoh: Atomic Habits"/></div>
        <div class="field"><label>Penulis *</label><input class="input" name="author" required maxlength="120" value="${esc(b?b.author:'')}" placeholder="Nama penulis"/></div>
        <div class="field"><label>Kategori</label><input class="input" name="category" maxlength="80" value="${esc(b?b.category:'')}" placeholder="Pengembangan Diri, Fiksi, dll"/></div>
        <div class="field"><label>Total Halaman *</label><input class="input" name="total_pages" type="number" min="1" required value="${esc(b?b.total_pages:0)}"/></div>
        <div class="field"><label>Status</label><select class="select" name="status"><option value="active" ${b&&b.status==='active'?'selected':''}>Aktif</option><option value="upcoming" ${b&&b.status==='upcoming'?'selected':''}>Mendatang</option><option value="archived" ${b&&b.status==='archived'?'selected':''}>Arsip</option></select></div>
        <div class="field"><label>Unggulan</label><select class="select" name="featured"><option value="false" ${!b||!b.featured?'selected':''}>Tidak</option><option value="true" ${b&&b.featured?'selected':''}>Ya, tampilkan di landing</option></select></div>
        <div class="field full"><label>Sinopsis</label><textarea class="textarea" name="synopsis" maxlength="5000" placeholder="Deskripsi singkat buku...">${esc(b?b.synopsis:'')}</textarea></div>
      </form>`,
    footer:`<button class="btn btn-secondary" onclick="BW.closeModal()">Batal</button><button class="btn btn-primary" id="saveBookBtn">${b?'Simpan Perubahan':'Tambah Buku'}</button>`
  });
  bindImageUpload('bookCoverUpload', {currentUrl:b?b.cover_url:''});
  $('#saveBookBtn').onclick = async () => {
    const form = $('#bookForm'); if(!form.reportValidity()) return;
    const btn = $('#saveBookBtn'); setBtnLoading(btn,true,'Menyimpan...');
    try {
      const fd = new FormData(form);
      const payload = Object.fromEntries(fd.entries());
      payload.id = b ? b.id : '';
      payload.featured = payload.featured === 'true';
      const upWrap = document.getElementById('bookCoverUpload');
      const imgPayload = upWrap._getPayload();
      const imgRemoved = upWrap._isRemoved();
      if(imgPayload) { payload.cover_image_base64 = imgPayload.image_base64; payload.cover_filename = imgPayload.filename; payload.cover_mime_type = imgPayload.mime_type; }
      if(imgRemoved) payload.remove_cover = true;
      const res = await api('saveBook', payload);
      await refreshData(true);
      closeModal();
      toast(res._message || (b?'Buku diperbarui.':'Buku ditambahkan.'));
      if(S.route==='bookDetail' && b) navigate('bookDetail', b.id); else if(S.route==='books') renderBooks($('#appContent'));
    } catch(err){ toast(err.message,'error'); setBtnLoading(btn,false); }
  };
}

function deleteBook(id) {
  const b = S.books.find(x=>x.id===id); if(!b) return;
  confirmDialog({ title:'Hapus Buku', message:`Hapus buku "${b.title}" secara permanen? Semua bab, log, diskusi, dan kuis terkait juga akan dihapus.`, confirmText:'Ya, Hapus', onConfirm: async ()=>{
    await api('deleteBook', {id});
    await refreshData(true);
    toast('Buku berhasil dihapus.');
    if(S.route==='bookDetail') navigate('books'); else renderBooks($('#appContent'));
  }});
}

/* ---------- Book Detail & Chapters ---------- */
function renderBookDetail(el, bookId) {
  const b = S.books.find(x=>x.id===bookId);
  if(!b){ el.innerHTML = emptyState(ICON_BOOK,'Buku tidak ditemukan','Buku mungkin telah dihapus.',`<button class="btn btn-primary btn-sm" onclick="BW.navigate('books')">Kembali</button>`); return; }
  const chapters = S.chapters.filter(c=>c.book_id===bookId).sort((a,b)=>Number(a.chapter_number)-Number(b.chapter_number));
  const bookLogs = (isAdmin()?S.allLogs:S.myLogs).filter(l=>l.book_id===bookId).slice(0,5);
  const bookDiscussions = S.discussions.filter(d=>d.book_id===bookId && !d.parent_id).slice(0,5);
  const bookQuizzes = S.quizzes.filter(q=>q.book_id===bookId);
  const progressLogs = S.myLogs.filter(l=>l.book_id===bookId);
  const maxPage = progressLogs.reduce((m,l)=>Math.max(m,Number(l.end_page||0)),0);
  const pct = b.total_pages ? Math.min(100, Math.round((maxPage/Number(b.total_pages))*100)) : 0;
  el.innerHTML = `
    <div style="margin-bottom:16px"><button class="btn btn-ghost btn-sm" onclick="BW.navigate('books')"><svg class="icon-sm" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M19 12H5M12 19l-7-7 7-7"/></svg>Kembali ke Katalog</button></div>
    <div class="panel" style="margin-bottom:24px">
      <div style="display:grid;grid-template-columns:220px 1fr;gap:24px;align-items:start" class="book-detail-grid">
        <div style="border-radius:16px;overflow:hidden;background:var(--bg-soft);aspect-ratio:3/4">${bookCoverHTML(b)}</div>
        <div>
          <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px"><span class="badge badge-primary">${esc(b.category||'Umum')}</span><span class="badge ${b.status==='active'?'badge-mint':b.status==='upcoming'?'badge-amber':'badge-slate'}">${esc(b.status)}</span>${b.featured?'<span class="badge badge-amber">Unggulan</span>':''}</div>
          <h2 style="font-family:var(--font-display);font-size:clamp(26px,3vw,36px);font-weight:800;color:var(--text);margin:0 0 8px;line-height:1.2">${esc(b.title)}</h2>
          <p style="font-size:16px;color:var(--text-muted);margin:0 0 16px">oleh <strong style="color:var(--text-body)">${esc(b.author||'-')}</strong> • ${Number(b.total_pages||0)} halaman • ${chapters.length} bab</p>
          <p style="font-size:16px;color:var(--text-body);line-height:1.75;margin:0 0 20px">${esc(b.synopsis||'Belum ada sinopsis.')}</p>
          <div style="margin-bottom:20px"><div style="display:flex;justify-content:space-between;font-size:14px;font-weight:600;color:var(--text-muted);margin-bottom:8px"><span>Progres baca Anda</span><span>${pct}% (${maxPage}/${Number(b.total_pages||0)})</span></div><div class="progress"><span style="width:${pct}%"></span></div></div>
          <div style="display:flex;gap:10px;flex-wrap:wrap">
            <button class="btn btn-primary" onclick="BW.openLogForm('${esc(b.id)}')">Catat Bacaan</button>
            ${isAdmin()?`<button class="btn btn-secondary" onclick="BW.openBookForm('${esc(b.id)}')">Edit Buku</button><button class="btn btn-secondary" onclick="BW.openChapterForm('${esc(b.id)}')">+ Bab</button>`:''}
          </div>
        </div>
      </div>
    </div>
    <div class="grid-2" style="gap:24px;align-items:start">
      <div class="panel">
        <div class="panel-header"><h3 class="panel-title">Daftar Bab</h3>${isAdmin()?`<button class="btn btn-secondary btn-sm" onclick="BW.openChapterForm('${esc(b.id)}')">+ Tambah Bab</button>`:''}</div>
        ${chapters.length?chapters.map(c=>`
          <div class="list-item">
            <div style="width:40px;height:40px;border-radius:10px;background:var(--primary-soft);color:var(--primary);display:grid;place-items:center;font-weight:800;font-size:14px;flex-shrink:0">${c.chapter_number}</div>
            <div class="list-item-body"><div class="list-item-title">${esc(c.title)}</div><div class="list-item-meta">${c.read_time_mins?c.read_time_mins+' menit baca • ':''}${fmtDate(c.created_at)}</div></div>
            <div class="list-item-actions">
              <button class="btn btn-ghost btn-sm" onclick="BW.openChapterRead('${esc(c.id)}')">Baca</button>
              ${isAdmin()?`<button class="btn btn-ghost btn-sm" onclick="BW.openChapterForm('${esc(b.id)}','${esc(c.id)}')">Edit</button><button class="btn btn-ghost btn-sm" style="color:var(--rose)" onclick="BW.deleteChapter('${esc(c.id)}','${esc(b.id)}')">Hapus</button>`:''}
            </div>
          </div>`).join(''):emptyState(ICON_BOOK,'Belum ada bab','Tambahkan bab untuk memandu pembaca.', isAdmin()?`<button class="btn btn-primary btn-sm" onclick="BW.openChapterForm('${esc(b.id)}')">Tambah Bab</button>`:'')}
      </div>
      <div style="display:grid;gap:24px">
        <div class="panel">
          <div class="panel-header"><h3 class="panel-title">Diskusi Buku</h3><button class="btn btn-ghost btn-sm" onclick="BW.navigate('discussions')">Semua</button></div>
          ${bookDiscussions.length?bookDiscussions.map(d=>`<div class="list-item"><div class="list-item-body"><div class="list-item-title">${esc(d.title||'Diskusi')}</div><div class="list-item-meta">${esc(d.user_name||'Pembaca')} • ${fmtDate(d.created_at)}</div></div></div>`).join(''):'<p class="text-muted text-sm">Belum ada diskusi untuk buku ini.</p>'}
          <div style="margin-top:12px"><button class="btn btn-secondary btn-sm" onclick="BW.openDiscussionForm('${esc(b.id)}')">Mulai Diskusi</button></div>
        </div>
        <div class="panel">
          <div class="panel-header"><h3 class="panel-title">Kuis</h3>${isAdmin()?`<button class="btn btn-ghost btn-sm" onclick="BW.openQuizForm(null,'${esc(b.id)}')">+ Kuis</button>`:''}</div>
          ${bookQuizzes.length?bookQuizzes.map(q=>`<div class="list-item"><div class="list-item-body"><div class="list-item-title">${esc(q.title)}</div><div class="list-item-meta">${(q.questions||[]).length} soal</div></div><div class="list-item-actions"><button class="btn btn-secondary btn-sm" onclick="BW.takeQuiz('${esc(q.id)}')">Kerjakan</button>${isAdmin()?`<button class="btn btn-ghost btn-sm" onclick="BW.openQuizForm('${esc(q.id)}')">Edit</button>`:''}</div></div>`).join(''):'<p class="text-muted text-sm">Belum ada kuis untuk buku ini.</p>'}
        </div>
      </div>
    </div>
    <style>@media(max-width:900px){.book-detail-grid{grid-template-columns:1fr!important}.book-detail-grid>div:first-child{max-width:260px}}</style>`;
}

function openChapterRead(chapterId) {
  const c = S.chapters.find(x=>x.id===chapterId); if(!c) return;
  const b = S.books.find(x=>x.id===c.book_id);
  openModal({
    title: `Bab ${c.chapter_number}: ${c.title}`,
    sub: b ? b.title : '',
    size:'lg',
    body: `<div style="font-size:16px;line-height:1.85;color:var(--text-body)">${c.content_html || '<p class="text-muted">Belum ada konten.</p>'}</div>${c.discussion_prompt?`<div style="margin-top:24px;padding:18px;background:var(--primary-soft);border-radius:14px"><strong style="color:var(--primary);display:block;margin-bottom:6px">Pertanyaan Diskusi</strong><span style="color:var(--text-body)">${esc(c.discussion_prompt)}</span></div>`:''}`,
    footer:`<button class="btn btn-secondary" onclick="BW.closeModal()">Tutup</button>`
  });
}

function openChapterForm(bookId, chapterId=null) {
  if(!isAdmin()) return;
  const c = chapterId ? S.chapters.find(x=>x.id===chapterId) : null;
  const bookChapters = S.chapters.filter(x=>x.book_id===bookId);
  const nextNum = c ? c.chapter_number : (bookChapters.reduce((m,x)=>Math.max(m,Number(x.chapter_number||0)),0)+1);
  openModal({
    title: c?'Edit Bab':'Tambah Bab',
    sub:'Susun materi bacaan per bab.',
    size:'lg',
    body:`<form id="chapterForm" class="form-grid">
      <div class="field"><label>Nomor Bab *</label><input class="input" name="chapter_number" type="number" min="1" required value="${esc(nextNum)}"/></div>
      <div class="field"><label>Estimasi Baca (menit)</label><input class="input" name="read_time_mins" type="number" min="0" value="${esc(c?c.read_time_mins:10)}"/></div>
      <div class="field full"><label>Judul Bab *</label><input class="input" name="title" required maxlength="200" value="${esc(c?c.title:'')}"/></div>
      <div class="field full"><label>Konten (HTML sederhana diperbolehkan)</label><textarea class="textarea" name="content_html" style="min-height:220px" placeholder="Tulis materi bab di sini...">${esc(c?c.content_html:'')}</textarea></div>
      <div class="field full"><label>Pertanyaan Diskusi</label><textarea class="textarea" name="discussion_prompt" style="min-height:90px" placeholder="Pertanyaan pemantik diskusi...">${esc(c?c.discussion_prompt:'')}</textarea></div>
    </form>`,
    footer:`<button class="btn btn-secondary" onclick="BW.closeModal()">Batal</button><button class="btn btn-primary" id="saveChapterBtn">Simpan Bab</button>`
  });
  $('#saveChapterBtn').onclick = async () => {
    const form=$('#chapterForm'); if(!form.reportValidity()) return;
    const btn=$('#saveChapterBtn'); setBtnLoading(btn,true,'Menyimpan...');
    try {
      const payload = Object.fromEntries(new FormData(form).entries());
      payload.id = c?c.id:''; payload.book_id = bookId;
      await api('saveChapter', payload);
      await refreshData(true); closeModal(); toast(c?'Bab diperbarui.':'Bab ditambahkan.');
      navigate('bookDetail', bookId);
    } catch(err){ toast(err.message,'error'); setBtnLoading(btn,false); }
  };
}
function deleteChapter(id, bookId) {
  const c=S.chapters.find(x=>x.id===id); if(!c) return;
  confirmDialog({title:'Hapus Bab', message:`Hapus bab "${c.title}"?`, confirmText:'Hapus Bab', onConfirm: async ()=>{
    await api('deleteChapter',{id}); await refreshData(true); toast('Bab dihapus.'); navigate('bookDetail',bookId);
  }});
}

/* ---------- Reading Logs ---------- */
function renderLogs(el) {
  const logs = (S.myLogs||[]).slice().sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));
  const pages = logs.reduce((s,l)=>s+Number(l.pages_read||0),0);
  el.innerHTML = `
    <div class="page-header"><div><h2>Jurnal Baca</h2><p>Catat progres, kutipan, dan refleksi bacaan Anda.</p></div><div class="page-header-actions"><button class="btn btn-primary" onclick="BW.openLogForm()"><svg class="icon-sm" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14M5 12h14"/></svg>Catat Bacaan</button></div></div>
    <div class="stat-grid" style="grid-template-columns:repeat(3,1fr)"><div class="stat-card"><div class="stat-label">Total Log</div><div class="stat-val">${logs.length}</div></div><div class="stat-card"><div class="stat-label">Halaman Dibaca</div><div class="stat-val">${pages}</div></div><div class="stat-card"><div class="stat-label">Streak</div><div class="stat-val">${calcStreak(logs)}</div></div></div>
    <div class="panel">
      <div class="panel-header"><h3 class="panel-title">Riwayat Jurnal</h3></div>
      ${logs.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Buku</th><th>Halaman</th><th>Durasi</th><th>Refleksi</th><th>Aksi</th></tr></thead><tbody>${logs.map(l=>`<tr>
        <td>${fmtDate(l.created_at)}</td>
        <td><strong style="color:var(--text)">${esc(l.book_title||'-')}</strong></td>
        <td>${Number(l.start_page||0)}-${Number(l.end_page||0)} <span class="text-muted">(${Number(l.pages_read||0)})</span></td>
        <td>${Number(l.duration_mins||0)} mnt</td>
        <td style="max-width:260px"><div style="display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden">${esc(l.reflection||l.quote||'-')}</div></td>
        <td><div style="display:flex;gap:6px"><button class="btn btn-ghost btn-sm" onclick="BW.openLogForm(null,'${esc(l.id)}')">Edit</button><button class="btn btn-ghost btn-sm" style="color:var(--rose)" onclick="BW.deleteLog('${esc(l.id)}')">Hapus</button></div></td>
      </tr>`).join('')}</tbody></table></div>`:emptyState(ICON_LOG,'Belum ada jurnal baca','Catat bacaan pertama Anda untuk mulai membangun kebiasaan.',`<button class="btn btn-primary btn-sm" onclick="BW.openLogForm()">Catat Bacaan</button>`)}
    </div>`;
}
function openLogForm(bookId=null, logId=null) {
  const l = logId ? S.myLogs.find(x=>x.id===logId) : null;
  const selectedBook = bookId || (l?l.book_id:'');
  openModal({
    title: l?'Edit Jurnal Baca':'Catat Bacaan',
    sub:'Rekam progres membaca Anda dengan detail.',
    size:'lg',
    body:`<form id="logForm" class="form-grid">
      <div class="field full"><label>Buku *</label><select class="select" name="book_id" required><option value="">Pilih buku...</option>${S.books.filter(b=>b.status!=='archived'||b.id===selectedBook).map(b=>`<option value="${esc(b.id)}" ${b.id===selectedBook?'selected':''}>${esc(b.title)} — ${esc(b.author||'')}</option>`).join('')}</select></div>
      <div class="field"><label>Halaman Mulai</label><input class="input" name="start_page" type="number" min="0" value="${esc(l?l.start_page:0)}"/></div>
      <div class="field"><label>Halaman Selesai *</label><input class="input" name="end_page" type="number" min="0" required value="${esc(l?l.end_page:0)}"/></div>
      <div class="field"><label>Halaman Dibaca</label><input class="input" name="pages_read" type="number" min="0" value="${esc(l?l.pages_read:0)}" placeholder="Otomatis jika kosong"/></div>
      <div class="field"><label>Durasi (menit)</label><input class="input" name="duration_mins" type="number" min="0" value="${esc(l?l.duration_mins:0)}"/></div>
      <div class="field full"><label>Kutipan Favorit</label><textarea class="textarea" name="quote" style="min-height:80px" placeholder="Kutipan yang berkesan...">${esc(l?l.quote:'')}</textarea></div>
      <div class="field full"><label>Refleksi / Insight</label><textarea class="textarea" name="reflection" placeholder="Apa yang Anda pelajari dari bacaan ini?">${esc(l?l.reflection:'')}</textarea></div>
      <div class="field full"><label>Visibilitas</label><select class="select" name="is_public"><option value="true" ${!l||l.is_public?'selected':''}>Publik (bisa dilihat komunitas)</option><option value="false" ${l&&!l.is_public?'selected':''}>Privat</option></select></div>
    </form>`,
    footer:`<button class="btn btn-secondary" onclick="BW.closeModal()">Batal</button><button class="btn btn-primary" id="saveLogBtn">${l?'Simpan Perubahan':'Simpan Jurnal'}</button>`
  });
  $('#saveLogBtn').onclick = async () => {
    const form=$('#logForm'); if(!form.reportValidity()) return;
    const btn=$('#saveLogBtn'); setBtnLoading(btn,true,'Menyimpan...');
    try {
      const payload = Object.fromEntries(new FormData(form).entries());
      payload.id = l?l.id:''; payload.is_public = payload.is_public==='true';
      await api('saveReadingLog', payload);
      await refreshData(true); closeModal(); toast(l?'Jurnal diperbarui.':'Jurnal berhasil disimpan.');
      renderRoute();
    } catch(err){ toast(err.message,'error'); setBtnLoading(btn,false); }
  };
}
function deleteLog(id) {
  const l=S.myLogs.find(x=>x.id===id); if(!l) return;
  confirmDialog({title:'Hapus Jurnal', message:`Hapus jurnal baca untuk "${l.book_title||'buku ini'}"?`, confirmText:'Hapus Jurnal', onConfirm: async ()=>{
    await api('deleteReadingLog',{id}); await refreshData(true); toast('Jurnal dihapus.'); renderRoute();
  }});
}

/* ---------- Discussions ---------- */
function renderDiscussions(el) {
  const topics = S.discussions.filter(d=>!d.parent_id).sort((a,b)=> (b.is_pinned?1:0)-(a.is_pinned?1:0) || String(b.created_at).localeCompare(String(a.created_at)));
  el.innerHTML = `
    <div class="page-header"><div><h2>Diskusi</h2><p>Berbagi insight, tanya jawab, dan diskusi buku bersama komunitas.</p></div><div class="page-header-actions"><button class="btn btn-primary" onclick="BW.openDiscussionForm()">Topik Baru</button></div></div>
    <div class="panel">
      ${topics.length?topics.map(d=>discussionItemHTML(d)).join(''):emptyState(ICON_CHAT,'Belum ada diskusi','Mulai topik diskusi pertama untuk komunitas Anda.',`<button class="btn btn-primary btn-sm" onclick="BW.openDiscussionForm()">Buat Topik</button>`)}
    </div>`;
}
function discussionItemHTML(d) {
  const replies = S.discussions.filter(x=>x.parent_id===d.id).sort((a,b)=>String(a.created_at).localeCompare(String(b.created_at)));
  const liked = (d.likes||[]).includes(S.user?.id);
  const book = S.books.find(b=>b.id===d.book_id);
  return `<div style="padding:20px 0;border-bottom:1px solid var(--border-soft)">
    <div style="display:flex;gap:14px;align-items:flex-start">
      ${avatarHTML({name:d.user_name,avatar_url:d.user_avatar},'sm')}
      <div style="flex:1;min-width:0">
        <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:4px">
          ${d.is_pinned?'<span class="badge badge-amber">Pinned</span>':''}
          ${book?`<span class="badge badge-slate">${esc(book.title)}</span>`:''}
        </div>
        <div style="font-family:var(--font-display);font-size:18px;font-weight:700;color:var(--text);margin-bottom:4px">${esc(d.title||'Diskusi')}</div>
        <div style="font-size:14px;color:var(--text-muted);margin-bottom:8px">${esc(d.user_name||'Pembaca')} • ${fmtDateTime(d.created_at)}</div>
        <div style="font-size:16px;color:var(--text-body);line-height:1.7;white-space:pre-wrap">${esc(d.content||'')}</div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px">
          <button class="btn btn-ghost btn-sm" onclick="BW.toggleLike('${esc(d.id)}')">${liked?'❤️':'🤍'} ${Number(d.likes_count|| (d.likes||[]).length||0)}</button>
          <button class="btn btn-ghost btn-sm" onclick="BW.openReplyForm('${esc(d.id)}')">Balas (${replies.length})</button>
          ${isAdmin()?`<button class="btn btn-ghost btn-sm" onclick="BW.togglePin('${esc(d.id)}')">${d.is_pinned?'Lepas Pin':'Pin'}</button>`:''}
          ${(isAdmin()||S.user?.id===d.user_id)?`<button class="btn btn-ghost btn-sm" onclick="BW.openDiscussionForm(null,'${esc(d.id)}')">Edit</button><button class="btn btn-ghost btn-sm" style="color:var(--rose)" onclick="BW.deleteDiscussion('${esc(d.id)}')">Hapus</button>`:''}
        </div>
        ${replies.length?`<div style="margin-top:14px;padding-left:12px;border-left:2px solid var(--border-soft);display:grid;gap:12px">${replies.map(r=>`<div style="background:var(--bg);border-radius:12px;padding:14px"><div style="font-size:14px;font-weight:700;color:var(--text);margin-bottom:2px">${esc(r.user_name||'Pembaca')} <span style="font-weight:500;color:var(--text-light)">• ${fmtDateTime(r.created_at)}</span></div><div style="font-size:15px;color:var(--text-body);white-space:pre-wrap">${esc(r.content||'')}</div>${(isAdmin()||S.user?.id===r.user_id)?`<div style="margin-top:8px"><button class="btn btn-ghost btn-sm" style="color:var(--rose);min-height:36px;padding:0 10px" onclick="BW.deleteDiscussion('${esc(r.id)}')">Hapus</button></div>`:''}</div>`).join('')}</div>`:''}
      </div>
    </div>
  </div>`;
}
function openDiscussionForm(bookId=null, editId=null) {
  const d = editId ? S.discussions.find(x=>x.id===editId) : null;
  openModal({
    title: d?'Edit Diskusi':'Topik Diskusi Baru',
    sub:'Bagikan pertanyaan atau insight bacaan Anda.',
    body:`<form id="discForm" class="form-grid">
      <div class="field full"><label>Buku (opsional)</label><select class="select" name="book_id"><option value="">Umum / Semua Buku</option>${S.books.map(b=>`<option value="${esc(b.id)}" ${(d?d.book_id:bookId)===b.id?'selected':''}>${esc(b.title)}</option>`).join('')}</select></div>
      ${(!d||!d.parent_id)?`<div class="field full"><label>Judul Topik *</label><input class="input" name="title" required maxlength="200" value="${esc(d?d.title:'')}"/></div>`:''}
      <div class="field full"><label>Isi Diskusi *</label><textarea class="textarea" name="content" required maxlength="5000" style="min-height:140px">${esc(d?d.content:'')}</textarea></div>
    </form>`,
    footer:`<button class="btn btn-secondary" onclick="BW.closeModal()">Batal</button><button class="btn btn-primary" id="saveDiscBtn">Simpan</button>`
  });
  $('#saveDiscBtn').onclick = async () => {
    const form=$('#discForm'); if(!form.reportValidity()) return;
    const btn=$('#saveDiscBtn'); setBtnLoading(btn,true,'Menyimpan...');
    try {
      const payload = Object.fromEntries(new FormData(form).entries());
      payload.id = d?d.id:''; payload.parent_id = d?d.parent_id:'';
      await api('saveDiscussion', payload); await refreshData(true); closeModal(); toast(d?'Diskusi diperbarui.':'Topik dibuat.'); renderRoute();
    } catch(err){ toast(err.message,'error'); setBtnLoading(btn,false); }
  };
}
function openReplyForm(parentId) {
  openModal({ title:'Balas Diskusi', sub:'Tulis balasan Anda.', size:'sm', body:`<form id="replyForm"><div class="field"><label>Balasan *</label><textarea class="textarea" name="content" required maxlength="2000" style="min-height:120px"></textarea></div></form>`, footer:`<button class="btn btn-secondary" onclick="BW.closeModal()">Batal</button><button class="btn btn-primary" id="sendReplyBtn">Kirim</button>` });
  $('#sendReplyBtn').onclick = async () => {
    const form=$('#replyForm'); if(!form.reportValidity()) return;
    const btn=$('#sendReplyBtn'); setBtnLoading(btn,true,'Mengirim...');
    try { await api('saveDiscussion',{parent_id:parentId, content:form.content.value, book_id:(S.discussions.find(d=>d.id===parentId)||{}).book_id||''}); await refreshData(true); closeModal(); toast('Balasan terkirim.'); renderRoute(); }
    catch(err){ toast(err.message,'error'); setBtnLoading(btn,false); }
  };
}
async function toggleLike(id){ try{ await api('toggleLikeDiscussion',{id}); await refreshData(true); renderRoute(); }catch(e){ toast(e.message,'error'); } }
async function togglePin(id){ try{ await api('togglePinDiscussion',{id}); await refreshData(true); renderRoute(); }catch(e){ toast(e.message,'error'); } }
function deleteDiscussion(id){ confirmDialog({title:'Hapus Diskusi', message:'Hapus diskusi ini? Balasan terkait juga akan dihapus jika ini topik utama.', confirmText:'Hapus', onConfirm: async ()=>{ await api('deleteDiscussion',{id}); await refreshData(true); toast('Diskusi dihapus.'); renderRoute(); }}); }

/* ---------- Quizzes ---------- */
function renderQuizzes(el) {
  const quizzes = S.quizzes.slice().sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));
  el.innerHTML = `
    <div class="page-header"><div><h2>Kuis Pemahaman</h2><p>Uji pemahaman bacaan dan lihat hasil Anda.</p></div><div class="page-header-actions">${isAdmin()?`<button class="btn btn-primary" onclick="BW.openQuizForm()">Buat Kuis</button>`:''}</div></div>
    <div class="panel">
      ${quizzes.length?`<div class="grid-2">${quizzes.map(q=>{
        const book=S.books.find(b=>b.id===q.book_id);
        const my=S.myQuizResults.filter(r=>r.quiz_id===q.id).sort((a,b)=>String(b.completed_at).localeCompare(String(a.completed_at)))[0];
        return `<div class="card" style="padding:20px"><div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px"><span class="badge badge-primary">${esc(book?book.title:'Umum')}</span><span class="badge badge-slate">${(q.questions||[]).length} soal</span></div><h3 style="font-family:var(--font-display);font-size:20px;font-weight:800;color:var(--text);margin:0 0 8px">${esc(q.title)}</h3><p style="font-size:15px;color:var(--text-muted);margin:0 0 14px;line-height:1.6">${esc(q.description||'')}</p>${my?`<div style="font-size:14px;font-weight:700;color:var(--mint);margin-bottom:14px">Skor terakhir: ${my.score}/100</div>`:''}<div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-primary btn-sm" onclick="BW.takeQuiz('${esc(q.id)}')">Kerjakan</button>${isAdmin()?`<button class="btn btn-secondary btn-sm" onclick="BW.openQuizForm('${esc(q.id)}')">Edit</button><button class="btn btn-ghost btn-sm" style="color:var(--rose)" onclick="BW.deleteQuiz('${esc(q.id)}')">Hapus</button>`:''}</div></div>`;
      }).join('')}</div>`:emptyState('<svg class="icon-lg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>','Belum ada kuis','Kuis akan membantu mengukur pemahaman bacaan.', isAdmin()?`<button class="btn btn-primary btn-sm" onclick="BW.openQuizForm()">Buat Kuis</button>`:'')}
    </div>`;
}
function openQuizForm(id=null, bookId=null) {
  if(!isAdmin()) return;
  const q = id ? S.quizzes.find(x=>x.id===id) : null;
  const questions = q ? (q.questions||[]) : [{question:'',options:['','','',''],correctIndex:0,explanation:''}];
  openModal({
    title: q?'Edit Kuis':'Buat Kuis',
    sub:'Buat soal pilihan ganda untuk menguji pemahaman.',
    size:'lg',
    body:`<form id="quizForm">
      <div class="form-grid">
        <div class="field"><label>Buku *</label><select class="select" name="book_id" required><option value="">Pilih buku...</option>${S.books.map(b=>`<option value="${esc(b.id)}" ${(q?q.book_id:bookId)===b.id?'selected':''}>${esc(b.title)}</option>`).join('')}</select></div>
        <div class="field"><label>Judul Kuis *</label><input class="input" name="title" required maxlength="200" value="${esc(q?q.title:'')}"/></div>
        <div class="field full"><label>Deskripsi</label><textarea class="textarea" name="description" style="min-height:80px">${esc(q?q.description:'')}</textarea></div>
      </div>
      <div style="margin-top:8px;margin-bottom:12px;font-weight:800;color:var(--text);font-family:var(--font-display)">Soal</div>
      <div id="quizQuestionsWrap">${questions.map((qq,i)=>quizQuestionHTML(qq,i)).join('')}</div>
      <button type="button" class="btn btn-secondary btn-sm mt-16" onclick="BW.addQuizQuestion()">+ Tambah Soal</button>
    </form>`,
    footer:`<button class="btn btn-secondary" onclick="BW.closeModal()">Batal</button><button class="btn btn-primary" id="saveQuizBtn">Simpan Kuis</button>`
  });
  $('#saveQuizBtn').onclick = async () => {
    const form=$('#quizForm'); if(!form.reportValidity()) return;
    const btn=$('#saveQuizBtn'); setBtnLoading(btn,true,'Menyimpan...');
    try {
      const fd = new FormData(form);
      const payload = { id:q?q.id:'', book_id:fd.get('book_id'), title:fd.get('title'), description:fd.get('description') };
      const qEls = $$('#quizQuestionsWrap .quiz-q-item');
      payload.questions = qEls.map((wrap,i)=>{
        return {
          question: wrap.querySelector('[name="question"]').value.trim(),
          options: Array.from(wrap.querySelectorAll('[name="option"]')).map(o=>o.value.trim()).filter(Boolean),
          correctIndex: Number(wrap.querySelector('[name="correctIndex"]').value||0),
          explanation: wrap.querySelector('[name="explanation"]').value.trim()
        };
      }).filter(x=>x.question && x.options.length>=2);
      if(!payload.questions.length) throw new Error('Minimal 1 soal dengan 2 opsi.');
      await api('saveQuiz', payload); await refreshData(true); closeModal(); toast(q?'Kuis diperbarui.':'Kuis dibuat.'); renderRoute();
    } catch(err){ toast(err.message,'error'); setBtnLoading(btn,false); }
  };
}
function quizQuestionHTML(q,i){
  const opts = (q.options&&q.options.length?q.options:['','','','']);
  while(opts.length<4) opts.push('');
  return `<div class="quiz-q-item card" style="padding:16px;margin-bottom:12px">
    <div style="display:flex;justify-content:space-between;gap:8px;margin-bottom:10px"><strong style="font-size:15px;color:var(--text)">Soal ${i+1}</strong><button type="button" class="btn btn-ghost btn-sm" style="color:var(--rose)" onclick="this.closest('.quiz-q-item').remove()">Hapus</button></div>
    <div class="field"><label>Pertanyaan *</label><input class="input" name="question" required value="${esc(q.question||'')}"/></div>
    <div class="form-grid">${opts.map((o,oi)=>`<div class="field"><label>Opsi ${String.fromCharCode(65+oi)}</label><input class="input" name="option" value="${esc(o||'')}" ${oi<2?'required':''}/></div>`).join('')}</div>
    <div class="form-grid"><div class="field"><label>Jawaban Benar (index 0-3)</label><input class="input" name="correctIndex" type="number" min="0" max="5" value="${Number(q.correctIndex||0)}"/></div><div class="field"><label>Pembahasan</label><input class="input" name="explanation" value="${esc(q.explanation||'')}"/></div></div>
  </div>`;
}
function addQuizQuestion(){ const w=$('#quizQuestionsWrap'); const i=w.querySelectorAll('.quiz-q-item').length; w.insertAdjacentHTML('beforeend', quizQuestionHTML({question:'',options:['','','',''],correctIndex:0,explanation:''},i)); }
function deleteQuiz(id){ const q=S.quizzes.find(x=>x.id===id); if(!q) return; confirmDialog({title:'Hapus Kuis', message:`Hapus kuis "${q.title}" dan semua hasilnya?`, confirmText:'Hapus Kuis', onConfirm: async ()=>{ await api('deleteQuiz',{id}); await refreshData(true); toast('Kuis dihapus.'); renderRoute(); }}); }
function takeQuiz(id){
  const q=S.quizzes.find(x=>x.id===id); if(!q) return;
  const qs=q.questions||[];
  openModal({ title:q.title, sub:`${qs.length} soal • Pilih jawaban terbaik`, size:'lg',
    body:`<form id="takeQuizForm">${qs.map((qq,i)=>`<div class="card" style="padding:18px;margin-bottom:14px"><div style="font-weight:700;color:var(--text);margin-bottom:12px;font-size:16px">${i+1}. ${esc(qq.question)}</div><div style="display:grid;gap:8px">${(qq.options||[]).map((opt,oi)=>`<label style="display:flex;gap:10px;align-items:flex-start;padding:12px 14px;border:1.5px solid var(--border);border-radius:12px;cursor:pointer"><input type="radio" name="q_${i}" value="${oi}" required style="margin-top:3px"/><span style="font-size:15px;color:var(--text-body)">${esc(opt)}</span></label>`).join('')}</div></div>`).join('')}</form>`,
    footer:`<button class="btn btn-secondary" onclick="BW.closeModal()">Batal</button><button class="btn btn-primary" id="submitQuizBtn">Kirim Jawaban</button>`
  });
  $('#submitQuizBtn').onclick = async ()=>{
    const form=$('#takeQuizForm'); if(!form.reportValidity()) return;
    const btn=$('#submitQuizBtn'); setBtnLoading(btn,true,'Mengirim...');
    try {
      const answers = qs.map((_,i)=>{ const v=form.querySelector(`input[name="q_${i}"]:checked`); return v?Number(v.value):-1; });
      const res = await api('submitQuizResult',{quiz_id:id, answers});
      await refreshData(true); closeModal();
      openModal({title:'Hasil Kuis', sub:q.title, size:'sm', body:`<div style="text-align:center;padding:12px 0"><div style="width:96px;height:96px;border-radius:50%;background:${res.score>=70?'var(--mint-soft)':'var(--amber-soft)'};color:${res.score>=70?'var(--mint)':'var(--amber)'};display:grid;place-items:center;font-family:var(--font-display);font-size:32px;font-weight:800;margin:0 auto 16px">${res.score}</div><p style="font-size:16px;color:var(--text-body);margin:0">Anda menjawab benar <strong>${res.correct}</strong> dari <strong>${res.total}</strong> soal.</p></div>`, footer:`<button class="btn btn-primary" onclick="BW.closeModal()">Tutup</button>`});
    } catch(err){ toast(err.message,'error'); setBtnLoading(btn,false); }
  };
}

/* ---------- Users (Admin) ---------- */
function renderUsers(el){
  if(!isAdmin()){ el.innerHTML='<div class="panel">Akses ditolak.</div>'; return; }
  const users=S.users||[];
  el.innerHTML=`
    <div class="page-header"><div><h2>Pengguna</h2><p>Kelola anggota, peran, dan status akun.</p></div><div class="page-header-actions"><button class="btn btn-primary" onclick="BW.openUserForm()">Tambah Pengguna</button></div></div>
    <div class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Pengguna</th><th>Email</th><th>Peran</th><th>Status</th><th>Dibuat</th><th>Aksi</th></tr></thead><tbody>
      ${users.map(u=>`<tr>
        <td><div style="display:flex;gap:10px;align-items:center">${avatarHTML(u,'sm')}<div><div style="font-weight:700;color:var(--text)">${esc(u.name)}</div><div style="font-size:13px;color:var(--text-light)">${esc(u.id)}</div></div></div></td>
        <td>${esc(u.email)}</td><td><span class="badge ${u.role==='admin'?'badge-primary':'badge-slate'}">${esc(u.role)}</span></td>
        <td><span class="badge ${u.status==='active'?'badge-mint':'badge-rose'}">${esc(u.status)}</span></td><td>${fmtDate(u.created_at)}</td>
        <td><div style="display:flex;gap:6px"><button class="btn btn-ghost btn-sm" onclick="BW.openUserForm('${esc(u.id)}')">Edit</button>${S.user?.id!==u.id?`<button class="btn btn-ghost btn-sm" style="color:var(--rose)" onclick="BW.deleteUser('${esc(u.id)}')">Hapus</button>`:''}</div></td>
      </tr>`).join('')}
    </tbody></table></div></div>`;
}
function openUserForm(id=null){
  if(!isAdmin()) return;
  const u=id?S.users.find(x=>x.id===id):null;
  openModal({title:u?'Edit Pengguna':'Tambah Pengguna', sub:'Kelola data akun dan avatar.', size:'lg', body:`<form id="userForm" class="form-grid">
    <div class="field full"><label>Avatar</label><div class="img-upload" id="userAvatarUpload">
      ${u&&u.avatar_url?`<img data-preview src="${esc(u.avatar_url)}" class="img-upload-preview avatar" style="display:block"/>`:`<img data-preview class="img-upload-preview avatar" style="display:none"/>`}
      <div data-placeholder style="${u&&u.avatar_url?'display:none':''};color:var(--text-muted);font-size:14px">Unggah avatar (opsional)</div>
      <div class="img-upload-actions"><label class="btn btn-secondary btn-sm" style="cursor:pointer"><input type="file" accept="image/*"/>Pilih Gambar</label><button type="button" class="btn btn-ghost btn-sm" data-remove>Hapus</button></div>
      <div class="field-hint" data-status></div></div></div>
    <div class="field"><label>Nama *</label><input class="input" name="name" required value="${esc(u?u.name:'')}"/></div>
    <div class="field"><label>Email *</label><input class="input" name="email" type="email" required value="${esc(u?u.email:'')}"/></div>
    <div class="field"><label>Peran</label><select class="select" name="role"><option value="member" ${u&&u.role==='member'?'selected':''}>Member</option><option value="admin" ${u&&u.role==='admin'?'selected':''}>Admin</option></select></div>
    <div class="field"><label>Status</label><select class="select" name="status"><option value="active" ${!u||u.status==='active'?'selected':''}>Aktif</option><option value="inactive" ${u&&u.status==='inactive'?'selected':''}>Nonaktif</option></select></div>
    <div class="field full"><label>${u?'PIN Baru (kosongkan jika tidak diubah)':'PIN (6 digit) *'}</label><input class="input" name="pin" inputmode="numeric" pattern="\\d{6}" maxlength="6" ${u?'':'required'} placeholder="123456"/></div>
    <div class="field full"><label>Bio</label><textarea class="textarea" name="bio" style="min-height:80px">${esc(u?u.bio:'')}</textarea></div>
  </form>`, footer:`<button class="btn btn-secondary" onclick="BW.closeModal()">Batal</button><button class="btn btn-primary" id="saveUserBtn">Simpan</button>`});
  bindImageUpload('userAvatarUpload',{currentUrl:u?u.avatar_url:''});
  $('#saveUserBtn').onclick = async ()=>{
    const form=$('#userForm'); if(!form.reportValidity()) return;
    const btn=$('#saveUserBtn'); setBtnLoading(btn,true,'Menyimpan...');
    try{
      const payload=Object.fromEntries(new FormData(form).entries()); payload.id=u?u.id:'';
      const up=document.getElementById('userAvatarUpload'); const img=up._getPayload(); if(img){payload.avatar_image_base64=img.image_base64; payload.avatar_filename=img.filename; payload.avatar_mime_type=img.mime_type;} if(up._isRemoved()) payload.remove_avatar=true;
      if(!payload.pin) delete payload.pin;
      await api('saveUser',payload); await refreshData(true); closeModal(); toast(u?'Pengguna diperbarui.':'Pengguna ditambahkan.'); renderRoute();
    }catch(err){ toast(err.message,'error'); setBtnLoading(btn,false); }
  };
}
function deleteUser(id){ const u=S.users.find(x=>x.id===id); if(!u) return; confirmDialog({title:'Hapus Pengguna', message:`Hapus pengguna "${u.name}"? Data terkait akan dibersihkan.`, confirmText:'Hapus Pengguna', onConfirm: async ()=>{ await api('deleteUser',{id}); await refreshData(true); toast('Pengguna dihapus.'); renderRoute(); }}); }

/* ---------- Settings ---------- */
function renderSettings(el){
  if(!isAdmin()){ el.innerHTML='<div class="panel">Akses ditolak.</div>'; return; }
  const s=S.settings||{};
  el.innerHTML=`<div class="page-header"><div><h2>Pengaturan Workspace</h2><p>Konfigurasi identitas, landing page, dan preferensi.</p></div></div>
  <form id="settingsForm" class="panel"><div class="form-grid">
    <div class="field full"><label>Logo Workspace</label><div class="img-upload" id="logoUpload">${s.logo_url?`<img data-preview src="${esc(s.logo_url)}" class="img-upload-preview" style="max-width:160px;aspect-ratio:1/1;object-fit:contain;display:block"/>`:`<img data-preview class="img-upload-preview" style="max-width:160px;aspect-ratio:1/1;object-fit:contain;display:none"/>`}<div data-placeholder style="${s.logo_url?'display:none':''};color:var(--text-muted);font-size:14px">Unggah logo</div><div class="img-upload-actions"><label class="btn btn-secondary btn-sm" style="cursor:pointer"><input type="file" accept="image/*"/>Pilih Gambar</label><button type="button" class="btn btn-ghost btn-sm" data-remove>Hapus</button></div><div class="field-hint" data-status></div></div></div>
    <div class="field"><label>Nama Workspace</label><input class="input" name="workspace_name" value="${esc(s.workspace_name||'')}"/></div>
    <div class="field"><label>Tagline</label><input class="input" name="workspace_tagline" value="${esc(s.workspace_tagline||'')}"/></div>
    <div class="field full"><label>Deskripsi</label><textarea class="textarea" name="workspace_description" style="min-height:90px">${esc(s.workspace_description||'')}</textarea></div>
    <div class="field full"><label>Pengumuman</label><input class="input" name="announcement" value="${esc(s.announcement||'')}"/></div>
    <div class="field"><label>Email Kontak</label><input class="input" name="contact_email" value="${esc(s.contact_email||'')}"/></div>
    <div class="field"><label>WhatsApp</label><input class="input" name="contact_whatsapp" value="${esc(s.contact_whatsapp||'')}"/></div>
    <div class="field"><label>Pendaftaran Publik</label><select class="select" name="allow_registration"><option value="true" ${String(s.allow_registration)!=='false'?'selected':''}>Aktif</option><option value="false" ${String(s.allow_registration)==='false'?'selected':''}>Nonaktif</option></select></div>
    <div class="field"><label>CTA Label</label><input class="input" name="landing_cta_label" value="${esc(s.landing_cta_label||'Mulai Membaca')}"/></div>
  </div><div style="display:flex;gap:10px;justify-content:flex-end;margin-top:8px"><button type="submit" class="btn btn-primary" id="saveSettingsBtn">Simpan Pengaturan</button></div></form>`;
  bindImageUpload('logoUpload',{currentUrl:s.logo_url||''});
  $('#settingsForm').onsubmit = async (e)=>{
    e.preventDefault(); const btn=$('#saveSettingsBtn'); setBtnLoading(btn,true,'Menyimpan...');
    try{
      const payload=Object.fromEntries(new FormData(e.target).entries());
      const up=document.getElementById('logoUpload'); const img=up._getPayload(); if(img){payload.logo_image_base64=img.image_base64; payload.logo_filename=img.filename; payload.logo_mime_type=img.mime_type;} if(up._isRemoved()) payload.remove_logo=true;
      await api('updateSettings',payload); await refreshData(true); toast('Pengaturan disimpan.'); renderRoute();
    }catch(err){ toast(err.message,'error'); setBtnLoading(btn,false); }
  };
}

/* ---------- Profile ---------- */
function renderProfile(el){
  const u=S.user||{};
  el.innerHTML=`<div class="page-header"><div><h2>Profil Saya</h2><p>Perbarui informasi akun dan avatar Anda.</p></div></div>
  <form id="profileForm" class="panel"><div class="form-grid">
    <div class="field full"><label>Avatar</label><div class="img-upload" id="profileAvatarUpload">${u.avatar_url?`<img data-preview src="${esc(u.avatar_url)}" class="img-upload-preview avatar" style="display:block"/>`:`<img data-preview class="img-upload-preview avatar" style="display:none"/>`}<div data-placeholder style="${u.avatar_url?'display:none':''};color:var(--text-muted);font-size:14px">Unggah avatar</div><div class="img-upload-actions"><label class="btn btn-secondary btn-sm" style="cursor:pointer"><input type="file" accept="image/*"/>Pilih Gambar</label><button type="button" class="btn btn-ghost btn-sm" data-remove>Hapus</button></div><div class="field-hint" data-status></div></div></div>
    <div class="field"><label>Nama</label><input class="input" name="name" required value="${esc(u.name||'')}"/></div>
    <div class="field"><label>Email</label><input class="input" name="email" type="email" required value="${esc(u.email||'')}"/></div>
    <div class="field full"><label>Bio</label><textarea class="textarea" name="bio" style="min-height:90px">${esc(u.bio||'')}</textarea></div>
    <div class="field"><label>PIN Lama (untuk ganti PIN)</label><input class="input" name="old_pin" inputmode="numeric" maxlength="6" placeholder="Hanya jika ganti PIN"/></div>
    <div class="field"><label>PIN Baru</label><input class="input" name="pin" inputmode="numeric" maxlength="6" placeholder="6 digit"/></div>
  </div><div style="display:flex;gap:10px;justify-content:flex-end;margin-top:8px"><button type="submit" class="btn btn-primary" id="saveProfileBtn">Simpan Profil</button></div></form>`;
  bindImageUpload('profileAvatarUpload',{currentUrl:u.avatar_url||''});
  $('#profileForm').onsubmit = async (e)=>{
    e.preventDefault(); const btn=$('#saveProfileBtn'); setBtnLoading(btn,true,'Menyimpan...');
    try{
      const payload=Object.fromEntries(new FormData(e.target).entries()); payload.id=u.id;
      const up=document.getElementById('profileAvatarUpload'); const img=up._getPayload(); if(img){payload.avatar_image_base64=img.image_base64; payload.avatar_filename=img.filename; payload.avatar_mime_type=img.mime_type;} if(up._isRemoved()) payload.remove_avatar=true;
      if(!payload.pin){ delete payload.pin; delete payload.old_pin; }
      await api('saveUser',payload); await refreshData(true); toast('Profil diperbarui.'); renderRoute();
    }catch(err){ toast(err.message,'error'); setBtnLoading(btn,false); }
  };
}

/* ---------- Auth ---------- */
function openAuth(mode='login'){
  closeModal();
  const isLogin = mode==='login';
  openModal({
    title: isLogin ? 'Masuk ke Buku Workspace' : 'Buat Akun Baru',
    sub: isLogin ? 'Lanjutkan perjalanan membaca Anda.' : 'Mulai membangun kebiasaan membaca hari ini.',
    size:'sm',
    body:`<form id="authForm">
      ${!isLogin?`<div class="field"><label>Nama Lengkap *</label><input class="input" name="name" required maxlength="100" placeholder="Nama Anda"/></div>`:''}
      <div class="field"><label>Email *</label><input class="input" name="email" type="email" required placeholder="nama@email.com"/></div>
      <div class="field"><label>PIN 6 Digit *</label><input class="input" name="pin" inputmode="numeric" pattern="\\d{6}" maxlength="6" required placeholder="123456"/></div>
      ${!isLogin?`<div class="field"><label>Bio (opsional)</label><input class="input" name="bio" maxlength="300" placeholder="Pembaca aktif..."/></div>`:''}
      <div style="font-size:14px;color:var(--text-muted);line-height:1.6">${isLogin?'Belum punya akun? <a href="#" onclick="BW.openAuth(\\'register\\');return false;" style="color:var(--primary);font-weight:700">Daftar</a>':'Sudah punya akun? <a href="#" onclick="BW.openAuth(\\'login\\');return false;" style="color:var(--primary);font-weight:700">Masuk</a>'}</div>
    </form>`,
    footer:`<button class="btn btn-secondary" onclick="BW.closeModal()">Batal</button><button class="btn btn-primary" id="authSubmitBtn">${isLogin?'Masuk':'Daftar'}</button>`
  });
  $('#authSubmitBtn').onclick = async ()=>{
    const form=$('#authForm'); if(!form.reportValidity()) return;
    const btn=$('#authSubmitBtn'); setBtnLoading(btn,true,isLogin?'Masuk...':'Mendaftar...');
    try{
      const payload=Object.fromEntries(new FormData(form).entries());
      const res = await api(isLogin?'login':'register', payload);
      S.token = res.token; S.user = res.user; saveSession();
      closeModal(); toast(isLogin?'Berhasil masuk.':'Akun berhasil dibuat.');
      await refreshData(true);
      enterApp();
    }catch(err){ toast(err.message,'error'); setBtnLoading(btn,false); }
  };
}

async function logout(){
  try{ if(CONFIG.API_URL && S.token) await api('logout',{}); }catch(e){}
  clearSession();
  S.myLogs=[]; S.myQuizResults=[]; S.users=[]; S.allLogs=[]; S.allQuizResults=[];
  $('#appShell').classList.remove('active');
  $('#landing-page').style.display='';
  document.body.classList.remove('modal-open');
  closeModal();
  location.hash='#home';
  toast('Anda telah keluar.');
}

/* ---------- Data / Bootstrap ---------- */
async function refreshData(silent=false){
  if(!CONFIG.API_URL){
    if(!silent) toast('API_URL belum diatur di theme.xml.','warn');
    return;
  }
  try{
    const data = await apiGet('initApp');
    applyInitData(data);
    if($('#appShell').classList.contains('active')) renderRoute();
  }catch(err){
    if(!silent) toast(err.message,'error');
    // fallback to cache
    const cached = cacheGet(); if(cached) applyInitData(cached);
  }
}

function enterApp(){
  $('#landing-page').style.display='none';
  $('#appShell').classList.add('active');
  updateUserUI();
  const hash = location.hash.replace(/^#\//,'');
  const parts = hash.split('/');
  if(ROUTES[parts[0]]){ S.route=parts[0]; S.routeParam=parts[1]?decodeURIComponent(parts[1]):null; }
  else { S.route='dashboard'; S.routeParam=null; location.hash='#/dashboard'; }
  renderRoute();
}

/* ---------- Landing helpers ---------- */
function scrollToSection(id){
  const landingVisible = $('#landing-page').style.display !== 'none';
  if(!landingVisible){
    // go back to landing
    $('#appShell').classList.remove('active');
    $('#landing-page').style.display='';
    location.hash = '#home';
  }
  closeMobileMenu();
  setTimeout(()=>{ const el=document.getElementById(id); if(el) el.scrollIntoView({behavior:'smooth',block:'start'}); }, 50);
}
function toggleMobileMenu(){ $('#mobileDrawer').classList.toggle('open'); }
function closeMobileMenu(){ $('#mobileDrawer')?.classList.remove('open'); }
document.addEventListener('click',(e)=>{ const nav=$('#landingNav'); if(nav && !nav.contains(e.target)) closeMobileMenu(); });
function toggleFaq(btn){ const item=btn.closest('.faq-item'); const wasOpen=item.classList.contains('open'); $$('.faq-item').forEach(i=>i.classList.remove('open')); if(!wasOpen) item.classList.add('open'); }

function initAnimations(){
  const obs = new IntersectionObserver((entries)=>{ entries.forEach(en=>{ if(en.isIntersecting){ en.target.classList.add('visible'); obs.unobserve(en.target); } }); }, {threshold:.12});
  $$('.fade-up,.stagger').forEach(el=>obs.observe(el));
}

function hydrateLanding(data){
  if(!data) return;
  const s=data.settings||{}; const stats=data.stats||{};
  if(s.workspace_name) $('#brandName').textContent = s.workspace_name;
  if(stats.books) $('#heroStatBooks').textContent = stats.books;
  if(stats.members) $('#heroStatMembers').textContent = stats.members;
  if(stats.reading_logs) $('#heroStatLogs').textContent = stats.reading_logs>999?(stats.reading_logs/1000).toFixed(1)+'k':stats.reading_logs;
  const books = data.featured_books || data.books || [];
  if(books.length){
    const grid = $('#landingBookGrid');
    grid.innerHTML = books.slice(0,4).map(b=>{
      const cover = b.cover_url ? `<img src="${esc(b.cover_url)}" alt="${esc(b.title)}" style="width:100%;height:100%;object-fit:cover" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'"/><div class="book-cover-placeholder" style="display:none">${esc(b.title)}</div>` : `<div class="book-cover-placeholder">${esc(b.title)}</div>`;
      const badge = b.featured?'<span class="book-badge badge badge-amber">Unggulan</span>':(b.status==='upcoming'?'<span class="book-badge badge badge-primary">Segera</span>':'');
      return `<div class="book-card"><div class="book-cover">${cover}${badge}</div><div class="book-body"><div class="book-cat">${esc(b.category||'Umum')}</div><h3 class="book-title">${esc(b.title)}</h3><p class="book-author">${esc(b.author||'-')}</p><div class="book-meta"><span>${Number(b.total_pages||0)} hal</span></div></div><div class="book-actions"><button class="btn btn-secondary btn-sm" onclick="BW.openAuth('register')">Mulai Baca</button></div></div>`;
    }).join('');
  }
}

async function boot(){
  loadSession();
  initAnimations();
  // Try loading public/initial data
  if(CONFIG.API_URL){
    try {
      const data = await apiGet('initApp');
      applyInitData(data);
      hydrateLanding(data);
      if(S.user && S.token){ enterApp(); return; }
    } catch(e){
      const cached = cacheGet(); if(cached){ applyInitData(cached); hydrateLanding(cached); }
      if(S.user && S.token){ enterApp(); return; }
    }
  } else {
    const cached = cacheGet(); if(cached){ applyInitData(cached); hydrateLanding(cached); }
    // Show landing with demo notice on first action
    console.warn('Buku Workspace: CONFIG.API_URL belum diatur.');
  }
  // Default: show landing
  $('#landing-page').style.display='';
  $('#appShell').classList.remove('active');
}

/* ---------- Public API ---------- */
window.BW = {
  navigate, renderBooks, openBookForm, deleteBook, openLogForm, deleteLog,
  openDiscussionForm, openReplyForm, toggleLike, togglePin, deleteDiscussion,
  openQuizForm, addQuizQuestion, deleteQuiz, takeQuiz,
  openUserForm, deleteUser, openChapterForm, openChapterRead, deleteChapter,
  openAuth, logout, refreshData, scrollToSection, toggleMobileMenu, toggleFaq,
  openMoreMenu, closeModal
};

boot();
})();
